from typing import List
import ctypes
import hashlib
import os
import subprocess
import sysconfig
import tempfile


_native_max_good_subarray = None


def _load_native():
    global _native_max_good_subarray
    if _native_max_good_subarray is not None:
        return _native_max_good_subarray

    c_code = r'''
#include <Python.h>
#include <stdint.h>
#include <stdlib.h>
#include <limits.h>

static inline uint64_t mix64(uint64_t x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static inline size_t find_slot(
    long long *keys,
    unsigned char *used,
    size_t mask,
    long long key
) {
    size_t p = (size_t)mix64((uint64_t)key) & mask;
    while (used[p] && keys[p] != key) {
        p = (p + 1) & mask;
    }
    return p;
}

long long maximumSubarraySum_native(PyObject *nums_obj, long long k) {
    PyObject *seq = PySequence_Fast(nums_obj, "nums must be a sequence");
    if (!seq) return 0;

    Py_ssize_t n_py = PySequence_Fast_GET_SIZE(seq);
    PyObject **items = PySequence_Fast_ITEMS(seq);
    size_t n = (size_t)n_py;

    size_t cap = 1;
    while (cap < n * 4 + 8) cap <<= 1;
    size_t mask = cap - 1;

    long long *keys = (long long *)malloc(cap * sizeof(long long));
    long long *vals = (long long *)malloc(cap * sizeof(long long));
    unsigned char *used = (unsigned char *)calloc(cap, sizeof(unsigned char));

    if (!keys || !vals || !used) {
        free(keys);
        free(vals);
        free(used);
        Py_DECREF(seq);
        return 0;
    }

    long long cur = 0;
    long long ans = LLONG_MIN;

    for (Py_ssize_t i = 0; i < n_py; ++i) {
        long long x = PyLong_AsLongLong(items[i]);

        size_t p = find_slot(keys, used, mask, x);
        if (!used[p]) {
            used[p] = 1;
            keys[p] = x;
            vals[p] = cur;
        } else if (cur < vals[p]) {
            vals[p] = cur;
        }

        cur += x;

        long long y1 = x - k;
        p = find_slot(keys, used, mask, y1);
        if (used[p]) {
            long long cand = cur - vals[p];
            if (cand > ans) ans = cand;
        }

        long long y2 = x + k;
        p = find_slot(keys, used, mask, y2);
        if (used[p]) {
            long long cand = cur - vals[p];
            if (cand > ans) ans = cand;
        }
    }

    free(keys);
    free(vals);
    free(used);
    Py_DECREF(seq);

    return ans == LLONG_MIN ? 0 : ans;
}
'''

    tmp = tempfile.gettempdir()
    digest = hashlib.sha256(c_code.encode()).hexdigest()[:16]
    so_path = os.path.join(tmp, f"max_good_subarray_{digest}.so")
    c_path = os.path.join(tmp, f"max_good_subarray_{digest}.c")

    if not os.path.exists(so_path):
        with open(c_path, "w") as f:
            f.write(c_code)

        include = sysconfig.get_paths()["include"]
        cc = os.environ.get("CC", "cc")

        subprocess.check_call([
            cc,
            "-O3",
            "-std=c99",
            "-shared",
            "-fPIC",
            c_path,
            "-I" + include,
            "-o",
            so_path,
        ])

    lib = ctypes.PyDLL(so_path)
    func = lib.maximumSubarraySum_native
    func.argtypes = [ctypes.py_object, ctypes.c_longlong]
    func.restype = ctypes.c_longlong

    _native_max_good_subarray = func
    return func


class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        return int(_load_native()(nums, k))
